interface LanguageContextValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: string) => string;
  caseText: (caseId: string, field: 'title' | 'summary' | 'location', fallback: string) => string;
}

const LanguageContext = createContext<LanguageContextValue | undefined>(undefined);
const STORAGE_KEY = 'the_third_eye_language';

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocale] = useState<Locale>('en');
  const [localeLoaded, setLocaleLoaded] = useState(false);

  useEffect(() => {
    const savedLocale = window.localStorage.getItem(STORAGE_KEY);
    if (savedLocale === 'en' || savedLocale === 'hi' || savedLocale === 'mr') setLocale(savedLocale);
    setLocaleLoaded(true);
  }, []);

  useEffect(() => {
    if (!localeLoaded) return;
    document.documentElement.lang = locale;
    window.localStorage.setItem(STORAGE_KEY, locale);
  }, [locale, localeLoaded]);

  const t = (key: string) => copy[locale][key] ?? copy.en[key] ?? key;
  const caseText = (caseId: string, field: 'title' | 'summary' | 'location', fallback: string) => {
    if (caseId === 'case-pcpc-wakad-2025') {
      const key = `case.benchmark.${field}`;
      return copy[locale]?.[key] ?? copy.en?.[key] ?? fallback;
    }
    if (caseId === 'case-pcpc-chakan-2025') {
      const key = `case.chakan.${field}`;
      return copy[locale]?.[key] ?? copy.en?.[key] ?? fallback;
    }
    if (caseId === 'case-pcpc-cyber-2025') {
      const key = `case.cyber.${field}`;
      return copy[locale]?.[key] ?? copy.en?.[key] ?? fallback;
    }
    if (caseId === 'case-pcpc-bhosari-2025') {
      const key = `case.bhosari.${field}`;
      return copy[locale]?.[key] ?? copy.en?.[key] ?? fallback;
    }
    if (caseId === 'case-pcpc-chikhali-2025') {
      const key = `case.chikhali.${field}`;
      return copy[locale]?.[key] ?? copy.en?.[key] ?? fallback;
    }
    return fallback;
  };

  return <LanguageContext.Provider value={{ locale, setLocale, t, caseText }}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within LanguageProvider');
  return context;
}